// Visual steps supplement the existing narrated review without changing exam grading.
const guidedVisual={key:'',index:0,animation:false,question:null,search:''};
function guidedVisualSection(s){
 const key=guided.lesson.unit+':'+s.id;if(guidedVisual.key!==key){guidedVisual.key=key;guidedVisual.index=0;guidedVisual.animation=false}
 return s.steps?.[guidedVisual.index];
}
window.guidedThermalText=s=>{const step=guidedVisualSection(s);return step?`Paso ${guidedVisual.index+1} de ${s.steps.length}. ${step.title}. ${step.text}.${guidedVisual.index===s.steps.length-1?' Al terminar este recorrido: '+s.pitfall:''}`:null};
window.guidedThermalHTML=s=>{
 const step=guidedVisualSection(s);if(!step)return '';
 return `<div class="guided-step-card"><div class="guided-step-top"><strong>PASO ${guidedVisual.index+1} DE ${s.steps.length}</strong><span>Figura propia · parte actual resaltada en ocre</span></div><h3>${esc(step.title)}</h3><p>${esc(step.text)}</p><figure class="guided-step-figure"><a href="${esc(step.image)}" target="_blank" rel="noopener" aria-label="Ampliar imagen del paso ${guidedVisual.index+1}"><img id="guided-step-image" src="${esc(guidedVisual.animation?s.animation:step.image)}" alt="${esc(guidedVisual.animation?'Animación del recorrido completo: '+s.title:step.alt)}" width="1000" height="620"></a><figcaption>${guidedVisual.animation?'GIF del recorrido completo: las zonas se resaltan en orden.':'La imagen acompaña este paso; tocala para ampliarla. Los textos explican el significado de las flechas.'}</figcaption></figure>
 ${guided.lesson.unit>=1&&guided.lesson.unit<=5?`<div class="practice-cta"><p><strong>Antes de continuar, identificá las partes en 3D.</strong><br>Practicá con números, funciones y fallas.</p><button id="guided-boiler-practice">Practicar</button></div>`:''}<div class="guided-step-tabs" aria-label="Pasos de la explicación">${s.steps.map((p,i)=>`<button class="secondary" data-guided-step="${i}" aria-current="${i===guidedVisual.index?'step':'false'}">${i+1}. ${esc(p.title)}</button>`).join('')}</div><div class="guided-step-navigation"><button class="secondary" id="guided-step-prev" ${guidedVisual.index===0?'disabled':''}>← Paso anterior</button><button id="guided-step-next" ${guidedVisual.index===s.steps.length-1?'disabled':''}>Siguiente paso →</button>${s.animation?`<button class="secondary" id="guided-animation" aria-pressed="${guidedVisual.animation}">${guidedVisual.animation?'Detener GIF · volver a imagen':'Reproducir GIF del recorrido'}</button>`:''}</div>
 ${s.plate?`<details class="guided-extra-plate"><summary>Ver esquema completo de referencia</summary><img loading="lazy" src="${esc(s.plate)}" alt="${esc(s.title)}: esquema completo para contrastar las conexiones" width="900"></details>`:''}
 <details class="guided-doc-prompts" open><summary>Preguntas del documento que prepara este recorrido (${s.questions.length})</summary><ol>${s.questions.map(q=>`<li value="${q.number}" class="${guidedVisual.question===q.number?'target-question':''}"><strong>${String(q.number).padStart(3,'0')}.</strong> ${esc(q.question)}</li>`).join('')}</ol><p class="source">Ensayá estas consignas después de recorrer los cuatro pasos. Las conexiones y maniobras concretas se completan con el plano del equipo.</p></details></div>`;
};
window.guidedThermalNav=lesson=>!lesson.documentQuestions?'':`<section class="guided-doc-finder" aria-label="Buscar entre las 150 preguntas del documento"><h2>Estudiar por pregunta del documento</h2><p>150 preguntas originales vinculadas con 37 recorridos y 148 pasos ilustrados. ${esc(lesson.documentNotice)}</p><label for="guided-doc-search">Número o tema</label><input id="guided-doc-search" type="search" value="${esc(guidedVisual.search)}" placeholder="Ej.: 074, cavitación, válvula o marcha atrás"><label for="guided-doc-select">Preguntas encontradas</label><select id="guided-doc-select" aria-describedby="guided-doc-results"></select><div class="actions"><button id="guided-open-question">Ir a la explicación paso a paso →</button><span id="guided-doc-results" role="status"></span></div></section>`;
function guidedSetVisual(index){guidedStop();const s=guided.lesson.sections[guided.index];guidedVisual.index=Math.max(0,Math.min(s.steps.length-1,index));guidedVisual.animation=false;guidedSection();document.querySelector('.guided-step-card h3')?.scrollIntoView({block:'nearest'})}
window.guidedAdvanceVisual=()=>{const s=guided.lesson.sections[guided.index];if(!s.steps||guidedVisual.index>=s.steps.length-1)return false;guidedVisual.index++;guidedVisual.animation=false;guidedSection();return true};
window.bindGuidedThermalSteps=()=>{
 document.querySelector("#guided-boiler-practice")?.addEventListener("click",()=>{const s=guided.lesson.sections[guided.index];window.startBoilerPractice?.(({"tipo-a":"A","tipo-m":"M","tipo-d":"D"})[s.id.replace(/^documento-/,"")]||"D")});
 document.querySelectorAll('[data-guided-step]').forEach(b=>b.onclick=()=>guidedSetVisual(+b.dataset.guidedStep));
 document.querySelector('#guided-step-prev')?.addEventListener('click',()=>guidedSetVisual(guidedVisual.index-1));document.querySelector('#guided-step-next')?.addEventListener('click',()=>guidedSetVisual(guidedVisual.index+1));
 document.querySelector('#guided-animation')?.addEventListener('click',()=>{guidedVisual.animation=!guidedVisual.animation;guidedSection()});
};
window.bindGuidedThermalNav=()=>{
 if(!guided.lesson.documentQuestions)return;
 const input=document.querySelector('#guided-doc-search'),select=document.querySelector('#guided-doc-select'),button=document.querySelector('#guided-open-question'),status=document.querySelector('#guided-doc-results');
 const norm=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 function filter(){guidedVisual.search=input.value;const term=norm(input.value.trim()),numeric=/^\d+$/.test(term);const results=guided.lesson.documentQuestions.filter(q=>!term||(numeric?q.number===Number(term):norm(q.question).includes(term)));select.innerHTML=results.map(q=>`<option value="${q.number}">${String(q.number).padStart(3,'0')} · U${q.unit+1} · ${esc(q.question)}</option>`).join('');button.disabled=!results.length;select.disabled=!results.length;status.textContent=results.length+' de 150 preguntas';if(results.some(q=>q.number===guidedVisual.question))select.value=guidedVisual.question;else if(!term){const q=results.find(q=>q.unit===guided.lesson.unit);if(q)select.value=q.number}}
 input.oninput=filter;filter();
 button.onclick=()=>{const q=guided.lesson.documentQuestions.find(q=>q.number===Number(select.value));if(!q)return;guidedVisual.question=q.number;guidedVisual.key='';if(q.unit===guided.lesson.unit){guidedGoSection(guided.lesson.sections.findIndex(s=>s.id===q.sectionId),{focus:true})}else renderGuidedReview(q.unit,{sectionId:q.sectionId})};
};
